extends Node2D

signal lap_completed(new_count: int)

var lap_count: int = 0
var passed_checkpoint: bool = false

@onready var start_line: Area2D = $StartLine
@onready var checkpoint: Area2D = $Checkpoint

func _ready() -> void:
    lap_count = 0
    passed_checkpoint = false
    if start_line:
        start_line.body_entered.connect(_on_start_line_body_entered)
    if checkpoint:
        checkpoint.body_entered.connect(_on_checkpoint_body_entered)

func _on_checkpoint_body_entered(body: Node) -> void:
    if body.is_in_group("car"):
        passed_checkpoint = true

func _on_start_line_body_entered(body: Node) -> void:
    if body.is_in_group("car") and passed_checkpoint:
        lap_count += 1
        passed_checkpoint = false
        print("LAP COMPLETE")
        emit_signal("lap_completed", lap_count)

func reset() -> void:
    lap_count = 0
    passed_checkpoint = false
    # Notify UI to reset display
    emit_signal("lap_completed", lap_count)
